def weighted_distance_sums(n: int, edges: list[list[int]], w: list[int]) -> list[int]:
    graph = [[] for _ in range(n)]
    for a, b in edges:
        graph[a].append(b)
        graph[b].append(a)

    parent = [-1] * n
    order = [0]
    for v in order:
        for nei in graph[v]:
            if nei != parent[v]:
                parent[nei] = v
                order.append(nei)

    subtree_weight = w[:]
    root_sum = 0
    depth = [0] * n

    for v in order:
        root_sum += w[v] * depth[v]
        for nei in graph[v]:
            if nei != parent[v]:
                depth[nei] = depth[v] + 1

    for v in reversed(order[1:]):
        subtree_weight[parent[v]] += subtree_weight[v]

    total_weight = subtree_weight[0]
    result = [0] * n
    result[0] = root_sum

    for v in order[1:]:
        p = parent[v]
        result[v] = result[p] + total_weight - 2 * subtree_weight[v]

    return result
